// Typeform-Antworten flach machen
const items = $input.all();
const answers = items[0].json.answers || [];
const hidden = items[0].json.hidden || {};
const result = {};

// Hidden Fields (UTM etc.) uebernehmen
Object.assign(result, hidden);

// Antworten auslesen
for (const answer of answers) {
  const ref = answer.field?.ref || answer.field?.id || 'unknown';
  switch (answer.type) {
    case 'email':
      result.email = answer.email;
      break;
    case 'text':
    case 'short_text':
    case 'long_text':
      result[ref] = answer.text;
      break;
    case 'choice':
      result[ref] = answer.choice?.label || '';
      break;
    case 'number':
      result[ref] = answer.number;
      break;
    case 'phone_number':
      result.phone = answer.phone_number;
      break;
    default:
      result[ref] = answer[answer.type];
  }
}

// Budget-Wert extrahieren
const budgetAnswer = answers.find(a => {
  const label = (a.choice?.label || a.text || '').toLowerCase();
  const ref = (a.field?.ref || '').toLowerCase();
  return ref.includes('budget') || label.includes('$') || label.includes('€') || ref.includes('invest');
});

if (budgetAnswer) {
  const budgetText = budgetAnswer.choice?.label || budgetAnswer.text || String(budgetAnswer.number || 0);
  const numbers = budgetText.match(/[\d.,]+/g);
  result.budget_raw = budgetText;
  result.budget_value = numbers ? parseInt(numbers[0].replace(/[.,]/g, '')) : 0;
} else {
  result.budget_raw = 'not found';
  result.budget_value = 0;
}

return [{ json: result }];

// Meta Conversions API Payload vorbereiten
const crypto = require('crypto');
const data = $input.first().json;

const hashSHA256 = (value) => {
  if (!value) return '';
  return crypto.createHash('sha256').update(value.trim().toLowerCase()).digest('hex');
};

const payload = {
  data: [{
    event_name: 'QualifiedLead',
    event_time: Math.floor(Date.now() / 1000),
    action_source: 'website',
    event_source_url: 'https://dsutrain.typeform.com',
    user_data: {
      em: data.email ? [hashSHA256(data.email)] : undefined,
      ph: data.phone ? [hashSHA256(data.phone)] : undefined
    },
    custom_data: {
      budget: data.budget_raw || '',
      budget_value: data.budget_value || 0,
      currency: 'USD'
    }
  }]
};

// Leere Felder entfernen
const ud = payload.data[0].user_data;
Object.keys(ud).forEach(key => {
  if (!ud[key]) delete ud[key];
});

return [{ json: payload }];
